import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf', 'docx'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_thumbnail(input_path, output_path):
    """Generate thumbnail using ImageMagick convert.
    We pass through the original filename to preserve metadata."""
    cmd = f"convert {input_path} -resize 200x200 -quality 85 {output_path}"
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f"Thumbnail generation failed: {result.stderr.decode()}")
    return output_path

def sanitize_path(user_input):
    """Basic path traversal prevention."""
    cleaned = user_input.replace('..', '').replace('//', '/')
    if cleaned.startswith('/'):
        cleaned = cleaned[1:]
    return cleaned

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    file.save(filepath)

    # Generate thumbnail for image files
    ext = filename.rsplit('.', 1)[1].lower()
    thumb_url = None
    if ext in {'png', 'jpg', 'jpeg', 'gif'}:
        thumb_path = os.path.join(UPLOAD_DIR, 'thumbs', f"thumb_{filename}")
        os.makedirs(os.path.dirname(thumb_path), exist_ok=True)
        try:
            generate_thumbnail(filepath, thumb_path)
            thumb_url = f"/files/thumbs/thumb_{filename}"
        except RuntimeError as e:
            app.logger.warning(f"Thumbnail failed: {e}")

    return jsonify({'status': 'uploaded', 'filename': filename, 'thumbnail': thumb_url}), 201

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded documents between formats using LibreOffice."""
    data = request.get_json()
    if not data or 'filename' not in data or 'target_format' not in data:
        return jsonify({'error': 'Missing parameters'}), 400

    filename = sanitize_path(data['filename'])
    target_format = data['target_format']

    # Validate target format
    valid_formats = ['pdf', 'docx', 'odt', 'txt', 'html']
    if target_format not in valid_formats:
        return jsonify({'error': 'Invalid target format'}), 400

    source_path = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(source_path):
        return jsonify({'error': 'File not found'}), 404

    output_dir = tempfile.mkdtemp(prefix='convert_')
    cmd = f"libreoffice --headless --convert-to {target_format} --outdir {output_dir} {source_path}"
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60)

    if result.returncode != 0:
        return jsonify({'error': 'Conversion failed'}), 500

    base_name = filename.rsplit('.', 1)[0]
    output_file = os.path.join(output_dir, f"{base_name}.{target_format}")

    if os.path.exists(output_file):
        return send_file(output_file, as_attachment=True)
    return jsonify({'error': 'Output file not generated'}), 500

@app.route('/files/<path:filepath>')
def serve_file(filepath):
    safe_path = sanitize_path(filepath)
    full_path = os.path.join(UPLOAD_DIR, safe_path)
    if os.path.exists(full_path) and os.path.isfile(full_path):
        return send_file(full_path)
    return jsonify({'error': 'Not found'}), 404

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
